<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {vocabularyStats,type VocabularyStats} from '@/api/vocabulary-stats'
import {errorMessage} from '@/api/identity'
import {useAuthStore} from '@/stores/auth'
import {getGeneration} from '@/auth/token-session'
import {useReadingRefresh} from '@/reading/useReadingRefresh'
const auth=useAuthStore(),data=ref<VocabularyStats>(),error=ref(''),loading=ref(false),weekdays=['一','二','三','四','五','六','日']
let sequence=0,controller:AbortController|undefined
async function load(){if(!auth.user)return;const current=++sequence,generation=getGeneration();controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const value=await vocabularyStats(controller.signal);if(current===sequence&&generation===getGeneration())data.value=value}catch(e){if(current===sequence&&generation===getGeneration()&&!(e instanceof DOMException&&e.name==='AbortError'))error.value=errorMessage(e)}finally{if(current===sequence)loading.value=false}}
watch(()=>auth.user?.id,()=>{sequence++;controller?.abort();data.value=undefined;error.value='';if(auth.user)void load()},{immediate:true,flush:'sync'})
useReadingRefresh(load,()=>!!auth.user)
onBeforeUnmount(()=>{sequence++;controller?.abort()})
</script>
<template><section class="vocabulary-stats" :aria-busy="loading" aria-labelledby="vs-title"><div class="vs-heading"><div><h2 id="vs-title">词汇学习</h2><p>新词与复习各自记录，积累不止于阅读。</p></div><RouterLink class="button-secondary" to="/vocabulary">去背单词</RouterLink></div><div v-if="error" class="reading-notice" role="alert"><p>{{ error }}</p><button class="button-secondary" :disabled="loading" @click="load">重试词汇统计</button></div><p v-if="loading&&!data" role="status" class="reader-rail-note">正在加载词汇记录…</p><template v-if="data"><dl class="vs-metrics"><div><dt>累计学习过</dt><dd>{{ data.totalLearned }} <small>词</small></dd></div><div><dt>成功复习</dt><dd>{{ data.totalReviewPasses }} <small>词次</small></dd></div><div><dt>现在到期</dt><dd>{{ data.due }} <small>词</small></dd></div><div><dt>完成轮次</dt><dd>{{ data.completedRounds }} <small>轮</small></dd></div></dl><dl class="vs-metrics" v-if="data.streakDays!=null"><div><dt>连续背词</dt><dd>{{data.streakDays}} <small>天</small></dd></div><div><dt>最长连续</dt><dd>{{data.longestStreak||0}} <small>天</small></dd></div><div><dt>无辅助独立复习</dt><dd>{{data.independentReviewPasses||0}}</dd></div><div><dt>难词</dt><dd>{{data.difficult||0}}</dd></div></dl><h3>本周单词积累</h3><p class="reader-rail-note">上海时间 · 同一单词每天新学/复习分别去重</p><ol class="vs-week"><li v-for="(day,index) in data.days" :key="day.date" class="vs-day" :class="{'has-record':day.newLearned+day.reviewed>0}" :aria-current="day.date===data.today?'date':undefined"><span>周{{ weekdays[index] }}</span><strong>{{ Number(day.date.slice(-2)) }}</strong><small>新学 {{ day.newLearned }}</small><small>复习 {{ day.reviewed }}</small></li></ol><details v-if="data.recentDays?.length" class="vs-month"><summary>近30天学习记录</summary><ol><li v-for="day in data.recentDays" :key="day.date"><span>{{day.date}}</span><span>新学 {{day.newLearned}}</span><span>复习 {{day.reviewed}}</span></li></ol></details><p v-if="!data.totalLearned" class="reader-rail-note">还没有词汇学习记录。将阅读生词加入学习，或选择参考词书，从一个词开始。</p><p v-else class="reader-rail-note">已暂停 {{ data.paused }} 词，历史保留。{{ data.nextDueAt?'下次复习：'+new Date(data.nextDueAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'暂无后续复习时间。' }}</p><p class="reader-rail-note">累计学习过不等于永久掌握；词汇练习不计入阅读打卡。</p></template></section></template>
<style scoped>
.vs-month{margin:25px 0;font-size:13px}.vs-month summary{cursor:pointer;color:#536b43}.vs-month ol{list-style:none;padding:0}.vs-month li{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #ece8ee;padding:10px 0}

.vocabulary-stats{margin-top:32px;padding:30px;border:1px solid #e7e3e9;border-radius:24px;background:var(--surface)}.vs-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.vs-heading h2{font-size:22px;margin:0}.vs-heading p{font-size:14px;color:#817a87;line-height:1.7}.vs-heading a{flex-shrink:0}.vs-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:22px;border-top:1px solid #ece8ee;padding-top:24px;margin:20px 0 30px}.vs-metrics dt{color:#817a87;font-size:13px}.vs-metrics dd{margin:15px 0;font-size:30px;font-weight:650}.vs-metrics small{font-size:13px;color:#817a87;font-weight:400}.vs-week{list-style:none;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px;padding:0}.vs-day{padding:18px 8px;border-radius:14px;background:var(--surface-2);display:flex;align-items:center;flex-direction:column;gap:10px;font-size:13px}.vs-day small{color:#87808b;white-space:nowrap;font-size:11px}.vs-day.has-record{background:var(--accent-soft)}.vs-day.has-record strong{color:var(--accent-dark)}.vs-day[aria-current=date]{box-shadow:inset 0 0 0 1px #e8bac9}.vocabulary-stats h3{font-size:17px}@media(max-width:700px){.vocabulary-stats{padding:22px 18px}.vs-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.vs-week{grid-template-columns:repeat(3,minmax(0,1fr))}.vs-heading{align-items:flex-start}.vs-heading h2{font-size:20px}.vs-heading a{font-size:12px;padding:10px}}
</style>
